1	import { readFileSync, existsSync } from 'fs';
2	import { join } from 'path';
3	import { Client } from "@modelcontextprotocol/sdk/client/index.js";
4	import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";
5	import type { Result, EngineOutput, MCPToolResult, MCPContent } from '../core/models.js';
6	import { SovereignDomain } from '../types/SovereignDomain.js';
7	import type { ToolRegistry } from '../ToolRegistry.js';
8	import type { SovereignConfig } from '../config/SovereignConfig.js';
9	import { createLogger } from "../utils/logger.js";
10	
11	const logger = createLogger('MCPEngine');
12	
13	interface MCPServerConfig {
14	    command: string;
15	    args: string[];
16	    env?: Record<string, string>;
17	}
18	
19	/**
20	 * MCPEngine - Universal Model Context Protocol Bridge
21	 */
22	export class MCPEngine {
23	    private readonly clients: Map<string, Client> = new Map();
24	
25	    constructor(
26	        private readonly config: SovereignConfig,
27	        private readonly registry: ToolRegistry
28	    ) { }
29	
30	    /**
31	     * Discovery: Loads POG2-mcp.json and bridges all defined servers.
32	     */
33	    public async initialize(): Promise<void> {
34	        const configPath = join(process.cwd(), 'POG2-mcp.json');
35	        if (!existsSync(configPath)) {
36	            logger.info('No POG2-mcp.json found. MCP bridge inactive.');
37	            return;
38	        }
39	
40	        try {
41	            const mcpConfig = JSON.parse(readFileSync(configPath, 'utf8'));
42	            const servers = mcpConfig.mcpServers || {};
43	
44	            for (const [name, config] of Object.entries(servers)) {
45	                await this.connectToServer(name, config as MCPServerConfig);
46	            }
47	        } catch (e) {
48	            logger.error({ error: (e as Error).message }, 'Failed to initialize MCP servers');
49	        }
50	    }
51	
52	    private async connectToServer(name: string, config: MCPServerConfig): Promise<void> {
53	        logger.info({ server: name }, 'Ã°Å¸â€Å’ Engaging MCP Neural Link...');
54	
55	        try {
56	            const transport = new StdioClientTransport({
57	                command: config.command,
58	                args: config.args || [],
59	                env: { ...process.env, ...config.env } as Record<string, string>
60	            });
61	
62	            const client = new Client(
63	                { name: "POG2-cli", version: "1.1.2" },
64	                { 
65	                    capabilities: { tools: {} },
66	                    requestTimeout: 60000 
67	                } as any
68	            );
69	
70	            await client.connect(transport);
71	            this.clients.set(name, client);
72	
73	            logger.info({ server: name }, 'Successfully connected to MCP server');
74	
75	            const toolsRes = await client.listTools();
76	            const tools = toolsRes.tools || [];
77	
78	            for (const t of tools) {
79	                this.registry.register({
80	                    name: `mcp_${name}_${t.name}`,
81	                    description: `[MCP:${name}] ${t.description}`,
82	                    domain: SovereignDomain.SYSTEM,
83	                    parameters: t.inputSchema as Record<string, unknown>,
84	                    execute: async (args): Promise<Result<EngineOutput>> => {
85	                        try {
86	                            const result = await client.callTool({
87	                                name: t.name,
88	                                arguments: args
89	                            }) as unknown as MCPToolResult;
90	
91	                            if (result.isError) {
92	                                const errorText = result.content.map((c: MCPContent) => c.text || JSON.stringify(c)).join('\n');
93	                                return { ok: false, error: new Error(errorText) };
94	                            }
95	
96	                            const output = result.content.map((c: MCPContent) => c.text || JSON.stringify(c)).join('\n') || 'Success';
97	                            return { ok: true, value: { output, data: { mcpContent: result.content } } };
98	                        } catch (err) {
99	                            logger.error({ server: name, tool: t.name, error: (err as Error).message }, 'MCP Tool Execution Failure');
100	                            return { ok: false, error: err as Error };
101	                        }
102	                    }
103	                });
104	            }
105	
106	            logger.info({ server: name, tools: tools.length }, 'âœ… MCP Neural Link Synchronized');
107	        } catch (err) {
108	            const errorMsg = (err as Error).stack || (err as Error).message;
109	            logger.error({ server: name, error: errorMsg }, 'âŒ MCP Neural Link Failure');
110	            // Try to provide hint about EPIPE if detected
111	            if (errorMsg.includes('EPIPE')) {
112	                logger.warn({ server: name }, 'EPIPE detected: This often means the server process crashed or stdout was polluted.');
113	            }
114	        }
115	    }
116	
117	    public async close(): Promise<void> {
118	        for (const [name, client] of this.clients.entries()) {
119	            try {
120	                await client.close();
121	                logger.debug({ server: name }, 'MCP Link offline');
122	            } catch (e) {
123	                logger.error({ server: name, error: (e as Error).message }, 'Failed to close MCP link');
124	            }
125	        }
126	    }
127	
128	    public healthCheck(): { online: boolean; details: string } {
129	        return { 
130	            online: true,
131	            details: `MCP Substrate: ${this.clients.size} active neural links.` 
132	        };
133	    }
134	}
